// Connect-ES API client — calls real backend via Connect-RPC.
// TS types generated by buf/protoc-gen-es (web/src/gen/.../srv_pb.ts).
//
// NOTE: the service descriptors are imported from the protoc-gen-es v2 files
// (*_pb.ts), which export GenService descriptors (structurally a DescService
// backed by serviceDesc(...)). The sibling *_connect.ts files were emitted by
// the older protoc-gen-connect-es v1 and reference message classes that no
// longer exist as values in the v2 proto code, so they neither type-check
// against the v2 runtime nor bundle. Importing from *_pb.ts gives full type
// inference for createClient with no casts.
import { createConnectTransport } from '@connectrpc/connect-web'
import { createClient, type Interceptor } from '@connectrpc/connect'
import { CatalogService, CatalogAdminService } from './gen/platform/v1/catalog/srv_pb.js'
import { RegistryAdminService } from './gen/platform/v1/registry/srv_pb.js'
import { LifecycleService } from './gen/platform/v1/lifecycle/srv_pb.js'
import { ApprovalDecision } from './gen/platform/v1/common/enum_pb.js'

// Transport: Connect-ES over HTTP to the Go backend.
// In dev, Vite proxies to localhost:8080. In production (go:embed), same origin.
const baseUrl = import.meta.env.DEV ? 'http://localhost:8080' : ''

// Attach the bearer token from localStorage to every outgoing request.
const authInterceptor: Interceptor = (next) => async (req) => {
  const token = localStorage.getItem('aether_token')
  if (token) {
    req.header.set('Authorization', `Bearer ${token}`)
  }
  return next(req)
}

export const transport = createConnectTransport({
  baseUrl,
  interceptors: [authInterceptor],
})

// Typed Connect clients. Fully typed via the v2 GenService descriptors.
export const catalogClient = createClient(CatalogService, transport)
export const catalogAdminClient = createClient(CatalogAdminService, transport)
export const registryClient = createClient(RegistryAdminService, transport)
export const lifecycleClient = createClient(LifecycleService, transport)

// === High-level API functions (used by pages) ===

export async function fetchCatalogItems() {
  const resp = await catalogClient.listItems({})
  return (resp.items || []).map(mapCatalogItem)
}

export async function fetchRequests() {
  const resp = await lifecycleClient.listRequests({})
  return (resp.requests || []).map(mapRequest)
}

export async function fetchPendingApprovals() {
  const resp = await lifecycleClient.listPendingApprovals({})
  // The backend returns approval runs (one per pending request). Map each run
  // into the display IaCRequest shape so the approvals table can render it.
  return (resp.runs || []).map((run: any) =>
    mapRequest({
      id: run.requestId,
      status: run.status,
      catalogItemId: '',
      envId: '',
      teamId: run.teamId || '',
      createdAt: run.startedAt || run.decidedAt || '',
    }),
  )
}

export async function fetchModules() {
  const resp = await registryClient.listModules({})
  return (resp.modules || []).map(mapModule)
}

// getCatalogItemDetail fetches a single catalog item including its
// form_schema_json (used to drive the RJSF dynamic request form).
export async function getCatalogItemDetail(id: string): Promise<CatalogItemDetail> {
  const resp = await catalogClient.getCatalogItem({ catalogItemId: id })
  const item = resp.item
  return {
    id: item?.id || id,
    name: item?.name || '',
    description: item?.description || '',
    category: item?.category || '',
    layer: item?.layerLogicalId || '',
    owner: item?.ownerTeamId || '',
    status: item?.status?.toString() || '',
    formSchemaJson: item?.formSchemaJson || '',
  }
}

export interface CatalogItemDetail extends CatalogItem {
  description: string
  formSchemaJson: string
}

// createRequest submits a lifecycle request. formData is the RJSF output
// (possibly nested / non-string values); it is flattened to map<string,string>
// to match the proto CreateRequest.form_values contract — each leaf value is
// JSON.stringified so the backend can recover typed values via json.Unmarshal.
export async function createRequest(input: {
  catalogItemId: string
  envId: string
  teamId: string
  formData: Record<string, unknown>
}): Promise<{ requestId: string; correlationId: string }> {
  const formValues: Record<string, string> = {}
  for (const [k, v] of Object.entries(input.formData || {})) {
    formValues[k] = typeof v === 'string' ? v : JSON.stringify(v)
  }
  const resp = await lifecycleClient.createRequest({
    catalogItemId: input.catalogItemId,
    envId: input.envId,
    teamId: input.teamId,
    formValues,
  })
  return {
    requestId: resp.request?.id || '',
    correlationId: resp.correlationId || '',
  }
}

export interface RegisterModuleInput {
  gitSource: string
  modulePath: string
  version: string
  provider: string
  name: string
  description?: string
  ownerTeamId: string
}

export interface RegisterModuleResult {
  moduleId: string
  moduleVersionId: string
  version: string
  status: string
}

// registerModule calls RegistryAdminService.RegisterModule and returns the new
// module + module_version IDs so the caller can immediately publish.
export async function registerModule(input: RegisterModuleInput): Promise<RegisterModuleResult> {
  const resp = await registryClient.registerModule({
    gitSource: input.gitSource,
    modulePath: input.modulePath,
    version: input.version,
    provider: input.provider,
    name: input.name,
    description: input.description ?? '',
    ownerTeamId: input.ownerTeamId,
  })
  const mod = resp.module
  const version = (mod?.versions && mod.versions[0]?.version) || input.version
  return {
    moduleId: mod?.id || '',
    moduleVersionId: resp.moduleVersionId || '',
    version,
    status: mod?.status?.toString() || '',
  }
}

export interface PublishCatalogInput {
  moduleVersionId: string
  displayName: string
  description?: string
  category: string
  layerLogicalId?: string
  ownerTeamId: string
  visibility?: string[]
}

// publishCatalogItem calls CatalogAdminService.PublishCatalogItem. The backend
// generates form_schema_json + defaults from the module version contract.
export async function publishCatalogItem(input: PublishCatalogInput): Promise<CatalogItem> {
  const resp = await catalogAdminClient.publishCatalogItem({
    moduleVersion: input.moduleVersionId,
    name: input.displayName,
    description: input.description ?? '',
    category: input.category,
    layerLogicalId: input.layerLogicalId ?? '',
    ownerTeamId: input.ownerTeamId,
    visibleToTeams: input.visibility ?? [],
  })
  return mapCatalogItem(resp.item)
}

export async function decideApproval(requestId: string, decision: 'approved' | 'rejected') {
  // The lifecycle RPC takes a run id + a numeric ApprovalDecision enum.
  await lifecycleClient.decideApproval({
    runId: requestId,
    decision: decision === 'approved' ? ApprovalDecision.APPROVED : ApprovalDecision.REJECTED,
  })
}

export async function fetchRequestDetail(id: string): Promise<RequestDetail> {
  const resp = await lifecycleClient.getRequest({ requestId: id })
  // mapRequest tolerates a missing/undefined request by defaulting every field.
  const r = mapRequest(resp.request)
  return {
    id: r.id || id,
    steps: [
      { title: '提交', description: '', status: 'finish' },
      { title: '代码生成', description: '', status: 'finish' },
      { title: 'Plan', description: '', status: 'finish' },
      { title: '审批', description: '', status: 'process' },
      { title: 'Apply', description: '', status: 'wait' },
      { title: '完成', description: '', status: 'wait' },
    ],
    timeline: [
      { color: 'green', content: '提交工单', time: r.createdAt },
    ],
    planDiff: '# Plan details will appear here',
    info: [
      { label: '资源', value: r.catalogItem },
      { label: '环境', value: r.env },
      { label: '状态', value: r.status },
    ],
  }
}

// === Type mappings (proto → frontend display types) ===

export type CatalogLayer = 'global' | 'middleware' | 'application'
export type CatalogCategory = 'database' | 'compute' | 'network' | 'storage' | 'middleware'
export type CatalogStatus = 'published' | 'draft' | 'deprecated'

// Env values cover both what the UI surfaces (dev/staging/prod) and the
// optional DR environment; backend values are mapped to these in mapRequest.
export type Env = 'dev' | 'staging' | 'prod' | 'dr'

// Status unions include both backend lifecycle values (from proto enums) and
// the human-facing values the pages render. Members intentionally form a
// superset so that Record<RequestStatus, string> tables in the pages are
// exhaustive regardless of which lifecycle value the backend returns.
export type RequestStatus =
  | 'succeeded'
  | 'pending_approval'
  | 'applying'
  | 'failed_terminal'
  | 'plan_ready'
  | 'generating'
  | 'failed_retryable'
  | 'rejected'
  | 'cancelled'
  | 'waiting_manual'
  | 'submitted'
  // UI-facing lifecycle values rendered by the pages:
  | 'draft'
  | 'code_generated'
  | 'completed'
  | 'failed'

// Module registry status values from the registry proto + UI-facing values.
export type ModuleStatus =
  | 'validated'
  | 'validation_failed'
  | 'deprecated'
  | 'ready'
  | 'extracting'
  | 'failed'
  | 'pending_validation'

export interface CatalogItem {
  id: string
  name: string
  category: string
  layer: string
  owner: string
  status: string
}

export interface IaCRequest {
  id: string
  catalogItem: string
  env: string
  status: string
  team: string
  createdAt: string
}

export interface Module {
  id: string
  name: string
  gitSource: string
  modulePath: string
  version: string
  provider: string
  varCount: number
  outputCount: number
  status: string
  contractJson?: string
  // moduleVersionId: snowflake ID of the current version, when surfaced by the
  // backend (ModuleVersion proto has no id field, so this is populated from the
  // register response and left empty for list rows — publishing from a list row
  // uses the dedicated publish modal where the operator supplies it).
  moduleVersionId?: string
}

export interface ApprovalItem extends IaCRequest {}

export interface RequestDetail {
  id: string
  steps: { title: string; description: string; status: 'finish' | 'process' | 'wait' | 'error' }[]
  timeline: { color: string; content: string; time?: string }[]
  planDiff: string
  info: { label: string; value: string }[]
}

function mapCatalogItem(item: any): CatalogItem {
  return {
    id: item.id || '',
    name: item.name || '',
    category: item.category || '',
    layer: item.layerLogicalId || '',
    owner: item.ownerTeamId || '',
    status: item.status?.toString() || '',
  }
}

function mapRequest(req: any): IaCRequest {
  return {
    id: req.id || '',
    catalogItem: req.catalogItemId || '',
    env: req.envId || '',
    status: req.status?.toString() || '',
    team: req.teamId || '',
    createdAt: req.createdAt || '',
  }
}

function mapModule(mod: any): Module {
  return {
    id: mod.id || '',
    name: mod.name || '',
    gitSource: mod.gitSource || '',
    modulePath: mod.modulePath || '',
    version: mod.version || '',
    provider: mod.provider || '',
    varCount: 0,
    outputCount: 0,
    status: mod.status?.toString() || '',
  }
}
